function toast(message,action=null){const el=$('#toast');el.replaceChildren();const copy=document.createElement('span');copy.className='toast-message';copy.textContent=message;el.append(copy);if(action?.label&&typeof action.onClick==='function'){const button=document.createElement('button');button.type='button';button.className='toast-action';button.textContent=action.label;button.setAttribute('aria-label',action.ariaLabel||action.label);button.addEventListener('click',async()=>{if(button.disabled)return;button.disabled=true;let failure=null,result=null;try{result=await action.onClick()}catch(error){failure=error}const successMessage=typeof action.successMessage==='function'?action.successMessage(result):action.successMessage;clearTimeout(toastTimer);el.classList.remove('show');setTimeout(()=>{el.replaceChildren();if(failure)toast(failure?.message||'That action could not be completed.');else if(successMessage)toast(successMessage)},250)});el.append(button)}el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.replaceChildren(),250)},action?9000:4500)}
