function invoiceDeleteBody(pending,{error='',confirmationValue=''}={}){const invoice=pending.snapshot,typed=`DELETE ${invoice.number}`,requiresExact=pending.requiresExactConfirmation===true;return `<div class="dialog-body invoice-delete-body"><p>Delete this invoice from the active ledger? You can restore it for 30 days from the confirmation toast or ask the owner bot to find it later.</p><dl class="detail-facts invoice-delete-facts"><div><dt>Invoice</dt><dd>${escape(invoice.number)}</dd></div><div><dt>Customer</dt><dd>${escape(invoice.client)}</dd></div><div><dt>Amount</dt><dd>${money(invoice.amount_minor,invoice.currency)}</dd></div><div><dt>Status</dt><dd>${escape(invoiceDeleteStatus(invoice))}</dd></div></dl>${requiresExact?`<label class="field delete-confirmation-field">Type <strong>${escape(typed)}</strong> to continue<input name="confirmation" autocomplete="off" autocapitalize="characters" spellcheck="false" required aria-describedby="delete-confirmation-help" value="${escape(confirmationValue)}"></label><small id="delete-confirmation-help" class="muted">This extra check protects an invoice with a payment or sent reminder.</small>`:''}<p class="error delete-error" data-delete-error role="alert">${escape(error)}</p></div>`}
