async function updateInvoice(x,patch){
  if((terminalInvoice(x)||!remaining(x))&&patch.followup_state!==undefined)throw Error('Paid, void, or cancelled invoices cannot have follow-up changed.');
  if(activeException(x)&&patch.followup_state==='approved')throw Error('Resolve the invoice exception before approving a draft.');
  if(activeException(x)?.type==='stop'&&Object.hasOwn(patch,'followup_exception'))throw Error('A STOP report requires separate consent review.');
  if(Object.hasOwn(patch,'followup_exception')){const report=patch.followup_exception;if(!report||!['paid_claim','dispute','stop'].includes(report.type)||typeof report.note!=='string'||!report.note.trim()||!Number.isFinite(Date.parse(report.recorded_at)))throw Error('Invalid invoice exception.');}
  const metadata={...(x.metadata||{}),followup_state:patch.followup_state??x.followup_state,reminder_text:patch.reminder_text??x.reminder_text};
  if(Object.hasOwn(patch,'followup_exception'))metadata.followup_exception=patch.followup_exception;
  if(Object.hasOwn(patch,'next_follow_up_at'))metadata.next_follow_up_at=patch.next_follow_up_at;
  if(Object.hasOwn(patch,'approved_reminder_text'))metadata.approved_reminder_text=patch.approved_reminder_text;
  if(Object.hasOwn(patch,'approved_preferences_updated_at'))metadata.approved_preferences_updated_at=patch.approved_preferences_updated_at;
  if(state.demo){Object.assign(x,patch,{metadata});return}
  const {data,error}=await db.from('invoices').update({metadata}).eq('workspace_id',state.workspace.id).eq('id',x.id).eq('updated_at',x.updated_at).select().single();
  if(error)throw Error(error.code==='PGRST116'?'This invoice changed. Refresh and try again.':error.message);
  const mapped=invoiceFromRow(data,state.customers,state.payments||[]);state.invoices=state.invoices.map(y=>y.id===x.id?mapped:y)
}
