// The invoice ledger itself is a drop target, so users never have to aim at a small file input.
let invoiceLedgerDragDepth=0;
function invoiceLedgerOverlay(show){let overlay=document.querySelector('.invoice-ledger-drop-overlay');if(show&&!overlay){overlay=document.createElement('div');overlay.className='invoice-ledger-drop-overlay';overlay.setAttribute('role','status');overlay.innerHTML=`<span>${icon('download')}</span><strong>Drop invoice to upload</strong><small>PDF, JPG, PNG or WEBP · one file at a time</small>`;document.body.append(overlay)}overlay?.classList.toggle('is-visible',show)}
document.addEventListener('dragenter',event=>{if(state.page!=='Invoices'||!event.dataTransfer?.types?.includes('Files')||$('#dialog')?.open)return;event.preventDefault();invoiceLedgerDragDepth++;invoiceLedgerOverlay(true)});
document.addEventListener('dragover',event=>{if(state.page==='Invoices'&&event.dataTransfer?.types?.includes('Files')&&!$('#dialog')?.open){event.preventDefault();event.dataTransfer.dropEffect='copy'}});
document.addEventListener('dragleave',event=>{if(!invoiceLedgerDragDepth)return;if(--invoiceLedgerDragDepth===0||event.relatedTarget===null)invoiceLedgerOverlay(false)});
document.addEventListener('drop',event=>{invoiceLedgerDragDepth=0;invoiceLedgerOverlay(false);if(state.page!=='Invoices'||$('#dialog')?.open)return;const file=event.dataTransfer?.files?.[0];if(!file)return;event.preventDefault();invoiceForm();const form=$('#invoice-form');ingestFile(form,file).catch(error=>{setIngestionState(form,error.message,'failed');showError(form,error)})});
